"""Build the claim registry from archived primary-source metadata."""
from pathlib import Path
import json, datetime, hashlib
R=Path(__file__).resolve().parent
S=R/'sources'
M={x['id']:x for x in json.loads((S/'manifest.json').read_text())}
P={x['source_id']:x for x in json.loads((S/'pinned-sources.json').read_text()) if x.get('same_bytes_as_snapshot')}
claims=[]
def add(id,claim,sources,section,boundary,gaps=None,release=None,cutoff='current_snapshot_verified',status='primary_verified'):
 refs=[]
 for sid,locator in sources:
  m=M[sid]
  assert m['status']=='retrieved',sid
  source_date = json.loads((S/f'{sid}.raw').read_text()).get('published_at') if sid.startswith('diffusers_release_v') else None
  refs.append({'source_id':sid,'url':P.get(sid,{}).get('url',m['url']),'retrieval_date':m['retrieved_at'],'source_release_date':source_date,'section':locator,'archive_raw':f"sources/{sid}.raw",'archive_text':f"sources/{sid}.txt",'raw_sha256':m['sha256'],'pin_verified_same_bytes':sid in P})
 if release and cutoff=='current_snapshot_verified': cutoff='release_event_within_cutoff_current_sources' if release<='2026-08-30' else 'post_cutoff_release_event'
 if status in ('proposal','manuscript_source_observation'):cutoff='not_a_historical_model_release_claim'
 claims.append({'id':id,'claim':claim,'report_section':section,'evidence_status':status,'release_date':release,'release_date_scope':'event or report date explicitly stated; null means not established','cutoff_class':cutoff,'sources':refs,'support_boundaries':boundary,'unresolved_gaps':gaps or []})
