lines=['# Primary-source catalogue','', 'Retrieval and hashes describe archived public responses, not first release dates. Failed/gated fetches are retained as gaps. See claims.json for claim-level boundaries.','']
for m in M.values():
 p=P.get(m['id'],{})
 lines += [f"## {m['id']}",f"- URL: {p.get('url',m['url'])}",f"- Retrieval: {m.get('retrieved_at','failed; no successful retrieval timestamp')}",f"- Status: {m['status']}",f"- Raw SHA-256: {m.get('sha256','not available')}",'']
(R/'source-catalogue.md').write_text('\n'.join(lines))
print('claims',len(claims),'sources',len(M))
